package io.invenlio.procurement;
import jakarta.servlet.http.HttpServletRequest;import java.net.URI;import java.util.Set;import org.slf4j.MDC;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice class ProcurementExceptionHandler{@ExceptionHandler(ProcurementException.class)ResponseEntity<ProblemDetail>handle(ProcurementException e,HttpServletRequest r){HttpStatus s=e.code().endsWith("NOT_FOUND")?HttpStatus.NOT_FOUND:Set.of("SUPPLIER_NUMBER_EXISTS","SUPPLIER_PRODUCT_EXISTS","SUPPLIER_SKU_EXISTS","PREFERRED_SUPPLIER_CONFLICT","CONCURRENT_MODIFICATION").contains(e.code())?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;return problem(s,e.code(),e.getMessage(),r);}@ExceptionHandler(DataIntegrityViolationException.class)ResponseEntity<ProblemDetail>integrity(DataIntegrityViolationException e,HttpServletRequest r){return problem(HttpStatus.CONFLICT,"PROCUREMENT_CONSTRAINT_VIOLATION","Conflicting procurement master data",r);}private ResponseEntity<ProblemDetail>problem(HttpStatus s,String code,String detail,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(s,detail);p.setType(URI.create("https://invenlio.io/problems/"+code.toLowerCase().replace('_','-')));p.setTitle(s.getReasonPhrase());p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",code);p.setProperty("correlationId",MDC.get("correlationId"));return ResponseEntity.status(s).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}}
